# React Error Boundary Component

## Implementation

```jsx
// ErrorBoundary.jsx
import React from "react";
import PropTypes from "prop-types";

// ─── Error Logger ────────────────────────────────────────────────────────────

const logError = (error, errorInfo, context = {}) => {
  const timestamp = new Date().toISOString();
  const errorDetails = {
    timestamp,
    message: error?.message,
    stack: error?.stack,
    componentStack: errorInfo?.componentStack,
    ...context,
  };

  // Console output with styling
  console.group(
    `%c⛔ React Error Boundary [${timestamp}]`,
    "color: #dc2626; font-weight: bold; font-size: 14px;"
  );
  console.error("Error:", error);
  console.error("Error Info:", errorInfo);
  console.groupCollapsed("Full Details");
  console.table({
    Message: errorDetails.message,
    Timestamp: errorDetails.timestamp,
  });
  console.error("Stack Trace:", errorDetails.stack);
  console.error("Component Stack:", errorDetails.componentStack);
  console.groupEnd();
  console.groupEnd();

  // Send to external monitoring service (e.g. Sentry, Datadog)
  if (typeof window.__errorLogger === "function") {
    window.__errorLogger(errorDetails);
  }

  return errorDetails;
};

// ─── Fallback UI ─────────────────────────────────────────────────────────────

const DefaultFallback = ({ error, errorInfo, onRetry, retryCount, maxRetries }) => {
  const [showDetails, setShowDetails] = React.useState(false);
  const canRetry = retryCount < maxRetries;

  return (
    <div role="alert" aria-live="assertive" style={styles.container}>
      <div style={styles.card}>
        {/* Icon */}
        <div style={styles.iconWrapper} aria-hidden="true">
          <svg
            width="56"
            height="56"
            viewBox="0 0 24 24"
            fill="none"
            stroke="#dc2626"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <circle cx="12" cy="12" r="10" />
            <line x1="12" y1="8" x2="12" y2="12" />
            <line x1="12" y1="16" x2="12.01" y2="16" />
          </svg>
        </div>

        {/* Message */}
        <h2 style={styles.title}>Something went wrong</h2>
        <p style={styles.subtitle}>
          {canRetry
            ? "An unexpected error occurred. You can try again or contact support if the problem persists."
            : "Maximum retry attempts reached. Please refresh the page or contact support."}
        </p>

        {/* Retry counter */}
        {retryCount > 0 && (
          <p style={styles.retryBadge}>
            Retry attempt {retryCount} of {maxRetries}
          </p>
        )}

        {/* Action buttons */}
        <div style={styles.actions}>
          {canRetry && (
            <button
              onClick={onRetry}
              style={styles.retryButton}
              onMouseEnter={(e) => (e.target.style.backgroundColor = "#b91c1c")}
              onMouseLeave={(e) => (e.target.style.backgroundColor = "#dc2626")}
            >
              ↻ Try Again
            </button>
          )}
          <button
            onClick={() => window.location.reload()}
            style={styles.reloadButton}
            onMouseEnter={(e) => (e.target.style.backgroundColor = "#e5e7eb")}
            onMouseLeave={(e) => (e.target.style.backgroundColor = "transparent")}
          >
            ⟳ Reload Page
          </button>
        </div>

        {/* Collapsible error details */}
        <div style={styles.detailsWrapper}>
          <button
            onClick={() => setShowDetails((prev) => !prev)}
            style={styles.detailsToggle}
            aria-expanded={showDetails}
          >
            {showDetails ? "▲ Hide" : "▼ Show"} error details
          </button>

          {showDetails && (
            <div style={styles.detailsBox} role="region" aria-label="Error details">
              <p style={styles.detailLabel}>Error Message</p>
              <pre style={styles.detailCode}>{error?.message ?? "Unknown error"}</pre>

              {error?.stack && (
                <>
                  <p style={styles.detailLabel}>Stack Trace</p>
                  <pre style={styles.detailCode}>{error.stack}</pre>
                </>
              )}

              {errorInfo?.componentStack && (
                <>
                  <p style={styles.detailLabel}>Component Stack</p>
                  <pre style={styles.detailCode}>{errorInfo.componentStack}</pre>
                </>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

// ─── Error Boundary Class ─────────────────────────────────────────────────────

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
      errorDetails: null,
      retryCount: 0,
      errorKey: 0, // Forces children to remount on retry
    };
    this.handleRetry = this.handleRetry.bind(this);
  }

  // ── Lifecycle ──────────────────────────────────────────────────────────────

  static getDerivedStateFromError(error) {
    // Synchronously update state so the fallback UI renders immediately
    return { hasError: true, error };
  }

  componentDidCatch(error, errorInfo) {
    const { onError, context } = this.props;

    const errorDetails = logError(error, errorInfo, {
      retryCount: this.state.retryCount,
      ...context,
    });

    this.setState({ errorInfo, errorDetails });

    // Notify parent via optional callback
    if (typeof onError === "function") {
      onError(error, errorInfo, errorDetails);
    }
  }

  componentDidUpdate(prevProps) {
    const { resetKeys } = this.props;
    const { hasError } = this.state;

    // Auto-reset when specified props change (similar to react-error-boundary)
    if (hasError && resetKeys && prevProps.resetKeys !== resetKeys) {
      const changed = resetKeys.some((key, i) => key !== prevProps.resetKeys?.[i]);
      if (changed) this.reset();
    }
  }

  // ── Helpers ────────────────────────────────────────────────────────────────

  reset() {
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
      errorDetails: null,
      errorKey: this.state.errorKey + 1,
    });
  }

  handleRetry() {
    const { maxRetries = 3, onRetry } = this.props;

    if (this.state.retryCount >= maxRetries) return;

    this.setState((prev) => ({
      hasError: false,
      error: null,
      errorInfo: null,
      errorDetails: null,
      retryCount: prev.retryCount + 1,
      errorKey: prev.errorKey + 1,
    }));

    if (typeof onRetry === "function") {
      onRetry(this.state.retryCount + 1);
    }
  }

  // ── Render ─────────────────────────────────────────────────────────────────

  render() {
    const { hasError, error, errorInfo, retryCount, errorKey } = this.state;
    const { children, fallback: CustomFallback, maxRetries = 3 } = this.props;

    if (hasError) {
      const fallbackProps = {
        error,
        errorInfo,
        onRetry: this.handleRetry,
        retryCount,
        maxRetries,
      };

      return typeof CustomFallback === "function" ? (
        <CustomFallback {...fallbackProps} />
      ) : CustomFallback ? (
        CustomFallback
      ) : (
        <DefaultFallback {...fallbackProps} />
      );
    }

    // key prop forces full remount of children on retry
    return <React.Fragment key={errorKey}>{children}</React.Fragment>;
  }
}

// ─── PropTypes ────────────────────────────────────────────────────────────────

ErrorBoundary.propTypes = {
  children: PropTypes.node.isRequired,
  fallback: PropTypes.oneOfType([PropTypes.func, PropTypes.node]),
  onError: PropTypes.func,
  onRetry: PropTypes.func,
  maxRetries: PropTypes.number,
  resetKeys: PropTypes.array,
  context: PropTypes.object,
};

ErrorBoundary.defaultProps = {
  maxRetries: 3,
};

// ─── HOC Helper ───────────────────────────────────────────────────────────────

export const withErrorBoundary = (Component, errorBoundaryProps = {}) => {
  const displayName = Component.displayName || Component.name || "Component";

  const WrappedComponent = (props) => (
    <ErrorBoundary {...errorBoundaryProps}>
      <Component {...props} />
    </ErrorBoundary>
  );

  WrappedComponent.displayName = `withErrorBoundary(${displayName})`;
  return WrappedComponent;
};

// ─── Hook (for triggering errors imperatively) ────────────────────────────────

export const useErrorHandler = () => {
  const [, setState] = React.useState();
  return React.useCallback((error) => {
    setState(() => {
      throw error;
    });
  }, []);
};

// ─── Styles ───────────────────────────────────────────────────────────────────

const styles = {
  container: {
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    minHeight: "100vh",
    padding: "24px",
    backgroundColor: "#f9fafb",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif",
  },
  card: {
    backgroundColor: "#ffffff",
    border: "1px solid #fee2e2",
    borderRadius: "12px",
    boxShadow: "0 4px 24px rgba(220, 38, 38, 0.08)",
    padding: "40px 48px",
    maxWidth: "560px",
    width: "100%",
    textAlign: "center",
  },
  iconWrapper: {
    display: "flex",
    justifyContent: "center",
    marginBottom: "20px",
  },
  title: {
    fontSize: "22px",
    fontWeight: "700",
    color: "#111827",
    margin: "0 0 12px",
  },
  subtitle: {
    fontSize: "15px",
    color: "#6b7280",
    lineHeight: "1.6",
    margin: "0 0 24px",
  },
  retryBadge: {
    display: "inline-block",
    backgroundColor: "#fef3c7",
    color: "#92400e",
    fontSize: "13px",
    fontWeight: "500",
    padding: "4px 12px",
    borderRadius: "999px",
    marginBottom: "20px",
  },
  actions: {
    display: "flex",
    gap: "12px",
    justifyContent: "center",
    marginBottom: "24px",
    flexWrap: "wrap",
  },
  retryButton: {
    backgroundColor: "#dc2626",
    color: "#ffffff",
    border: "none",
    borderRadius: "8px",
    padding: "10px 24px",
    fontSize: "15px",
    fontWeight: "600",
    cursor: "pointer",
    transition: "background-color 0.15s ease",
  },
  reloadButton: {
    backgroundColor: "transparent",
    color: "#374151",
    border: "1px solid #d1d5db",
    borderRadius: "8px",
    padding: "10px 24px",
