export default ErrorBoundary;
```

## Usage Examples

```jsx
// App.jsx — Basic usage
import ErrorBoundary from "./ErrorBoundary";
import { withErrorBoundary, useErrorHandler } from "./ErrorBoundary";

// ── 1. Basic Wrapper ──────────────────────────────────────────────────────────
const App = () => (
  <ErrorBoundary
    maxRetries={3}
    onError={(error, info, details) => console.log("Captured:", details)}
    onRetry={(attempt) => console.log(`Retry attempt #${attempt}`)}
  >
    <MainContent />
  </ErrorBoundary>
);

// ── 2. Custom Fallback Component ──────────────────────────────────────────────
const MyFallback = ({ error, onRetry, retryCount, maxRetries }) => (
  <div>
    <h2>Oops! {error?.message}</h2>
    <button onClick={onRetry} disabled={retryCount >= maxRetries}>
      Retry ({retryCount}/{maxRetries})
    </button>
  </div>
);

const AppWithCustomFallback = () => (
  <ErrorBoundary fallback={MyFallback}>
    <Dashboard />
  </ErrorBoundary>
);

// ── 3. HOC Pattern ────────────────────────────────────────────────────────────
const SafeWidget = withErrorBoundary(Widget, {
  maxRetries: 2,
  context: { location: "sidebar" },
  onError: (error) => analytics.track("widget_error", { error: error.message }),
});

// ── 4. Auto-reset on prop change ──────────────────────────────────────────────
const UserProfile = ({ userId }) => (
  <ErrorBoundary resetKeys={[userId]}>
    <ProfileCard userId={userId} />
  </ErrorBoundary>
);

// ── 5. useErrorHandler — trigger boundary from async code ─────────────────────
const DataFetcher = () => {
  const throwError = useErrorHandler();

  React.useEffect(() => {
    fetch("/api/data")
      .then((r) => r.json())
      .catch((err) => throwError(err)); // Sends error to nearest boundary
  }, [throwError]);

  return <div>Loading...</div>;
};

// ── 6. Buggy component for testing ───────────────────────────────────────────
const BuggyComponent = () => {
  const [shouldCrash, setShouldCrash] = React.useState(false);
  if (shouldCrash) throw new Error("💥 Test error triggered!");
  return (
    <button onClick={() => setShouldCrash(true)}>
      Trigger Error
    </button>
  );
};
```

## Architecture Overview

```
┌─────────────────────────────────────────────────────────┐
│                     ErrorBoundary                        │
│                                                          │
│  getDerivedStateFromError()  ──►  hasError = true        │
│                                                          │
│  componentDidCatch()         ──►  logError()             │
│                                   ├─ console.group       │
│                                   ├─ console.table       │
│                                   └─ window.__errorLogger│
│                                                          │
│  render()                                                │
│   ├─ hasError=false  ──►  <children key={errorKey} />   │
│   └─ hasError=true   ──►  <Fallback />                  │
│                             ├─ DefaultFallback           │
│                             └─ CustomFallback            │
└──────────────────────┬──────────────────────────────────┘
                       │ handleRetry()
                       ▼
           retryCount++, errorKey++
           Children fully remounted
```

## Key Design Decisions

| Feature | Implementation Detail |
|---|---|
| **Retry isolation** | `errorKey` increments force full children remount, clearing stale state |
| **Max retries** | Configurable cap (default 3); disables button and shows reload option |
| **Auto-reset** | `resetKeys` prop re-mounts children when watched values change |
| **Error propagation** | `onError` callback lets parents/analytics tools receive structured details |
| **Async errors** | `useErrorHandler` hook bridges `Promise` rejections into the boundary |
| **Custom fallback** | Accepts a component function (with props) or a static React node |
| **External logging** | Checks `window.__errorLogger` for drop-in Sentry/Datadog integration |
